        '                    continue\n'
        '                if sys.platform == "win32":\n'
        '                    import msvcrt\n'
        '                    while msvcrt.kbhit():\n'
        '                        if not config.get("_steer_active"):\n'
        '                            _buf = ""\n'
        '                            break\n'
        '                        ch = msvcrt.getwch()\n'
